function load(){try{const x=JSON.parse(localStorage.getItem(KEY));return x?.version===3?x:null}catch{return null}}
let S=load()||seed(); if(!Array.isArray(S.documents))S.documents=[];if(!Array.isArray(S.docTasks))S.docTasks=[];const save=()=>{try{localStorage.setItem(KEY,JSON.stringify(S))}catch{toast('Nie udało się zapisać danych na urządzeniu.',true)}};if(!load())save();
let ui={page:'dashboard',search:'',filter:'all',modal:null,modalExtra:{},menu:false,importTarget:'products',docTab:'queue',docsMine:false};
const product=id=>S.products.find(x=>x.id===id);
const investor=id=>S.investors.find(x=>x.id===id);
const supplier=id=>S.suppliers.find(x=>x.id===id);
const order=id=>S.orders.find(x=>x.id===id);
const getName=(v,key)=>v?.[key]||'Nieznany';
const orderTotal=o=>(o.lines||[]).reduce((a,l)=>a+n(l.qty)*n(l.price)*(1-n(l.discount)/100),0);
const orderCost=o=>(o.lines||[]).reduce((a,l)=>a+n(l.qty)*n(l.unitCost??product(l.id)?.cost),0);
const orderMargin=o=>orderTotal(o)?(orderTotal(o)-orderCost(o))/orderTotal(o):0;
const orderVat=o=>orderTotal(o)*(1+n(S.finance.vat)/100);
const reserved=(id)=>S.orders.filter(o=>['approved','picking','ready'].includes(o.status)).reduce((s,o)=>s+o.lines.filter(l=>l.id===id).reduce((a,l)=>a+n(l.qty),0),0);
const available=id=>n(product(id)?.stock)-reserved(id);
const salaryCost=p=>n(p.count)*n(p.gross)*(1+n(p.bonus)/100)*(1+n(S.finance.employer)/100+n(S.finance.ppk)/100*n(S.finance.ppkShare)/100);
const wageCost=()=>S.people.reduce((a,p)=>a+salaryCost(p),0);
const vehicleCost=v=>n(v.km)*n(v.liters)/100*n(S.finance.fuelPrice)+['lease','insurance','service','tyres','tolls','other'].reduce((sum,k)=>sum+n(v[k]),0);
const fleetCost=()=>S.vehicles.reduce((a,v)=>a+vehicleCost(v),0);
function financeCalc(){let revenue=S.finance.lines.reduce((a,x)=>a+n(x.revenue),0),cogs=S.finance.lines.reduce((a,x)=>a+n(x.cogs),0);let gross=revenue-cogs,payroll=wageCost(),fleet=fleetCost(),ebitda=gross-payroll-fleet-n(S.finance.opex),ebit=ebitda-n(S.finance.depreciation),pretax=ebit-n(S.finance.interest),cit=Math.max(0,pretax*n(S.finance.cit)/100),net=pretax-cit;return {revenue,cogs,gross,payroll,fleet,ebitda,ebit,pretax,cit,net,margin:revenue?gross/revenue:0,netMargin:revenue?net/revenue:0}}
function addEvent(description){S.events.unshift({at:new Date().toISOString(),role:ROLE[role].name,description});S.events=S.events.slice(0,200)}
function persist(description){if(description)addEvent(description);save();render()}
function toast(message,error=false){document.querySelector('.toast')?.remove();let t=document.createElement('div');t.className='toast'+(error?' error':'');t.setAttribute('role','status');t.textContent=message;document.body.appendChild(t);setTimeout(()=>t.remove(),3800)}
const tag=(s)=>{let a={'draft':['Szkic','dark'],'approved':['Zatwierdzone','blue'],'picking':['W kompletacji','amber'],'ready':['Gotowe do wysyłki','green'],'transit':['W trasie','blue'],'delivered':['Dostarczone','green'],'settled':['Rozliczone','green'],'ordered':['Zamówione','blue'],'received':['Przyjęte','green'],'planned':['Planowane','dark'],'loading':['Załadunek','amber'],'done':['Zakończone','green'],'open':['Otwarte','red'],'closed':['Zamknięte','green'],'review':['Do kontroli','amber'],'accepted':['Zweryfikowany','green'],'rejected':['Do poprawy','red']}[s]||[s,'dark'];return `<span class="tag ${a[1]}">${e(a[0])}</span>`};
const btn=(name,action,variant='btn-primary',attrs='')=>`<button class="btn ${variant}" data-action="${action}" ${attrs}>${name}</button>`;
const card=(label,val,foot)=>`<div class="stat"><div class="stat-label">${label}</div><div class="stat-value">${val}</div><div class="stat-foot">${foot}</div></div>`;
const panel=(title,sub,content,actions='')=>`<section class="panel"><div class="panel-head"><div><h2 class="panel-title">${title}</h2>${sub?`<div class="panel-sub">${sub}</div>`:''}</div>${actions}</div>${content}</section>`;
const table=(headers,rows)=>`<div class="table-scroll"><table class="data-table"><thead><tr>${headers.map(h=>`<th>${h}</th>`).join('')}</tr></thead><tbody>${rows.join('')||`<tr><td colspan="${headers.length}" class="empty">Brak pozycji dla tego filtra.</td></tr>`}</tbody></table></div>`;
const tr=(cells)=>`<tr>${cells.map(c=>`<td>${c}</td>`).join('')}</tr>`;
function head(title,subtitle,actions=''){return `<div class="page-head"><div><div class="eyebrow">Centrum operacyjne / 2026</div><h1>${title}</h1><p class="subtitle">${subtitle}</p></div><div class="page-actions">${actions}</div></div>`}
function searchbar(placeholder='Szukaj...'){return `<div class="search">${icon('search')}<input class="input" id="search" placeholder="${e(placeholder)}" value="${e(ui.search)}" aria-label="Szukaj"/></div>`}
function selectfilter(arr){return `<select id="filter" class="select short" aria-label="Filtr"><option value="all">Wszystkie</option>${arr.map(([v,l])=>`<option value="${v}" ${ui.filter===v?'selected':''}>${l}</option>`).join('')}</select>`}
function statusSection(){let count=S.orders.filter(x=>['draft','approved','picking','ready'].includes(x.status)).length,low=S.products.filter(p=>available(p.id)<p.min).length,credit=S.investors.filter(p=>p.balance>p.credit).length;return {count,low,credit}}
function dashboard(){let f=financeCalc(),st=statusSection(),v=S.vehicles.length;let financial=can('finance'),stats=financial?[card('Sprzedaż netto / plan',PLN(f.revenue),'Przychód miesięczny bez VAT'),card('Marża brutto',PLN(f.gross),PCT(f.margin)+' plan sprzedaży'),card('EBITDA / scenariusz',PLN(f.ebitda),'Po kosztach pracy, floty i OPEX'),card('Zamówienia w obsłudze',st.count,'W aktywnym procesie')]:[card('Aktywne zamówienia',st.count,'W realizacji'),card('Dostawy do obsługi',S.trips.filter(t=>t.status!=='delivered').length,'W planowaniu i trasie'),card('Towary poniżej minimum',st.low,'Wymagają uzupełnienia'),card('Flota pojazdów',v,'HDS i pojazdy dostawcze')];
let summary=S.finance.lines.map((d,i)=>{let margin=n(d.revenue)?(n(d.revenue)-n(d.cogs))/n(d.revenue):0;return `<div class="bar-row"><strong>${['Budowlana','Elektryczna','Tartak','Transport'][i]}</strong><div class="progress"><span style="width:${Math.min(100,margin*180)}%;background:${['#1f619a','#ca2b3c','#197d8e','#71879b'][i]}"></span></div><span class="driver-value">${PCT(margin)}</span></div>`}).join('');
let orderRows=S.orders.slice(0,5).map(o=>tr([`<strong>${e(o.id)}</strong><small>${e(investor(o.clientId)?.name)}</small>`,e(investor(o.clientId)?.project),PLN(orderTotal(o)),tag(o.status)]));let action=can('orders.write')?btn(icon('plus')+' Nowe zamówienie','new-order'):'',alerts=[...S.products.filter(p=>available(p.id)<p.min).map(p=>({text:p.name+' · stan dostępny '+NUM(available(p.id),0)+' '+p.unit,kind:'amber'})),...S.investors.filter(i=>i.balance>i.credit).map(i=>({text:i.name+' · przekroczony limit o '+PLN(i.balance-i.credit),kind:'red'}))];
if(can('documents.review')){let pending=S.documents.filter(d=>d.status==='review').length,missing=S.trips.filter(t=>t.status==='delivered'&&!approvedDoc('trip',t.id,'POD')).length;if(pending)alerts.unshift({text:`Dokumenty w kolejce biura: ${pending}`,kind:'red'});if(missing)alerts.unshift({text:`Dostawy bez zatwierdzonego POD: ${missing}`,kind:'amber'});let blocked=S.trips.filter(t=>t.issue&&!t.issueResolved).length;if(blocked)alerts.unshift({text:`Nierozliczone szkody i braki: ${blocked}`,kind:'red'})}
let p1=panel('Struktura marży według działów','Plan miesięczny; marża handlowa przed kosztami wspólnymi',`<div class="panel-content">${summary}<div class="note">Wynik tartaku ma własną kalkulację surowca i uzysku. Transport własny nie podwaja przychodów.</div></div>`,can('finance')?btn('Pełny wynik '+icon('arrow'),'go-finance','btn btn-small'):'');
let p2=panel('Wymaga uwagi',`${st.low} pozycji magazynowych · ${st.credit} przekroczony limit`, `<div class="panel-content"><div class="vlist">${alerts.slice(0,5).map(a=>`<div class="vlist-row"><div><strong>${icon('alert')} ${e(a.text)}</strong></div><span class="tag ${a.kind}">Alert</span></div>`).join('')||'<p class="note">Brak aktywnych alertów.</p>'}</div></div>`,btn('Wszystkie ryzyka','go-risks','btn btn-small'));
return head('Przegląd działalności','Wyniki, operacje i zdarzenia wymagające reakcji na jednym ekranie.',action)+`<section class="hero-banner"><div class="hero-copy"><span class="hero-kicker">SYSTEM ZARZĄDZANIA CENTRUM</span><h2>Wszystkie działy.<br><em>Jeden rytm pracy.</em></h2><p>Sprzedaż, budowy, tartak i transport HDS w jednym obiegu informacji.</p><div class="hero-pills"><span>${S.vehicles.filter(v=>v.type.includes('HDS')).length} pojazdy HDS</span><span>${Object.keys(CATEGORIES).length} centra wyniku</span><span>${S.people.reduce((a,p)=>a+n(p.count),0)} etaty</span></div></div><div class="hero-art" aria-label="Wizualizacja centrum budowlanego, składu materiałów oraz transportu HDS" role="img"></div></section><div class="stats">${stats.join('')}</div><div class="photo-modules">${[
['stock','SKŁAD MATERIAŁÓW','Hurtownia budowlana','construction','bud'],
['stock','INSTALACJE','Hurtownia elektryczna','electric','ele'],
['sawmill','DREWNO I PRODUKCJA','Tartak','lumber',''],
['fleet','DOSTAWY NA BUDOWY','Transport HDS','logistics','']]
.filter(([p])=>can(p)).map(([p,tagline,name,photo,cat])=>`<button class="photo-module photo-${photo}" type="button" data-nav="${p}" ${cat?`data-category="${cat}"`:''} aria-label="Otwórz ${name}"><span class="photo-label">${tagline}</span><strong>${name} ${icon('arrow')}</strong></button>`).join('')}</div><div class="quick-action-row" aria-label="Szybkie operacje">${[
['orders.write','plus','Nowe zamówienie','new-order',true],
['documents.upload','file','Dodaj dokument','new-doc-general',true],
['imports','download','Import CSV / XLSX','imports',false],
['orders','download','Eksport zamówień','export-orders',true],
['finance','chart','Wynik firmy','finance',false],
['fleet','truck','Plan dostaw','fleet',false],
['investors','clients','Inwestorzy','investors',false],
['risks','shield','Ryzyka i BHP','risks',false]
].filter(([right])=>can(right)).map(([right,ic,label,act,isAction])=>`<button type="button" class="quick-action" ${isAction?'data-action':'data-nav'}="${act}">${icon(ic)}<span>${label}</span></button>`).join('')}</div><div class="cols">${financial?p1:panel('Przekrój zamówień','Według statusów',`<div class="panel-content">${['draft','approved','picking','ready','transit','delivered'].map(s=>`<div class="inline-line">${tag(s)}<strong>${S.orders.filter(o=>o.status===s).length}</strong></div>`).join('')}</div>`)}${p2}</div>`+panel('Ostatnie zamówienia','Przekrój przez hurtownię budowlaną, elektryczną i tartak',table(['Numer / inwestor','Inwestycja','Wartość netto','Status'],orderRows),btn('Lista zamówień '+icon('arrow'),'go-orders','btn btn-small'))+`<div class="cols equal">${panel('Dzisiejsze operacje','Uproszczony dziennik czynności',`<div class="panel-content vlist">${S.events.slice(0,4).map(x=>`<div class="vlist-row"><div><strong>${e(x.description)}</strong><small>${e(x.role)} · ${new Date(x.at).toLocaleString('pl-PL')}</small></div></div>`).join('')}</div>`)}${panel('Model przedsiębiorstwa','Jedna firma, oddzielne centra kosztów',`<div class="panel-content"><div class="grid2">${[['Budowlana','Materiały budowlane','warehouse'],['Elektryczna','Kable i osprzęt','finance'],['Tartak','Surowiec i produkcja','tree'],['HDS','Dostawy i flota','truck']].map(([a,b,ic])=>`<div class="profile department-tile"><span class="dept-icon">${icon(ic)}</span><div><strong>${a}</strong><small style="display:block;color:#849198;margin-top:5px">${b}</small></div></div>`).join('')}</div><p class="note">Każdy dział ma własną marżę, a koszty wspólne są rozliczane na poziomie centrum.</p></div>`)}</div>`}
function ordersPage(){let filter=['draft','approved','picking','ready','transit','delivered','settled'].map(s=>[s,{draft:'Szkice',approved:'Zatwierdzone',picking:'Kompletacja',ready:'Gotowe',transit:'W trasie',delivered:'Dostarczone',settled:'Rozliczone'}[s]]);let q=ui.search.toLowerCase();let rows=S.orders.filter(o=>(ui.filter==='all'||o.status===ui.filter)&&[o.id,investor(o.clientId)?.name,investor(o.clientId)?.project,o.note].join(' ').toLowerCase().includes(q)).map(o=>{let options='';if(o.status==='draft'&&can('orders.approve'))options=btn('Zatwierdź','approve-order','btn-small',`data-id="${o.id}"`);if(['approved','picking'].includes(o.status)&&can('orders.pick'))options=btn('Następny etap','pick-order','btn-small',`data-id="${o.id}"`);if(o.status==='ready'&&can('fleet.write'))options=btn('Zaplanuj HDS','trip-order','btn-small',`data-id="${o.id}"`);if(o.status==='delivered'&&can('orders.settle'))options=btn('Rozlicz','settle-order','btn-small',`data-id="${o.id}"`);return tr([`<strong>${e(o.id)}</strong><small>${DATE(o.created)}</small>`,`<strong>${e(investor(o.clientId)?.name)}</strong><small>${e(investor(o.clientId)?.project)}</small>`,`${o.lines.length} pozycji`,PLN(orderTotal(o)),`<span class="amount" style="color:${orderMargin(o)<.12?'#c94d4c':'#168267'}">${PCT(orderMargin(o))}</span>`,tag(o.status),options||'<span class="muted">-</span>'])});let actions=can('orders.write')?btn(icon('plus')+' Nowe zamówienie','new-order'):'';return head('Zamówienia','Sprzedaż wielodziałowa, marże, rezerwacje i pełny cykl realizacji.',actions)+`<div class="alert blue">${icon('shield')} Uprawnienia są sprawdzane przed zmianą statusu. Zatwierdzenie kontroluje marżę, limit inwestora i dostępność towaru. Wydanie WZ następuje przy rozpoczęciu dostawy.</div><div class="toolbar">${searchbar('Numer, klient, inwestycja...')}${selectfilter(filter)}${btn(icon('download')+' CSV','export-orders','btn')}</div>`+panel('Rejestr zamówień',S.orders.length+' zamówienia w lokalnej bazie',table(['Zamówienie','Klient / budowa','Pozycje','Netto','Marża','Status','Działanie'],rows));}
function investorsPage(){let q=ui.search.toLowerCase(),rows=S.investors.filter(i=>[i.name,i.project,i.stage].join(' ').toLowerCase().includes(q)).map(i=>tr([`<strong>${e(i.name)}</strong><small>${e(i.project)}</small>`,e(i.stage),PLN(i.credit),PLN(i.balance),`<div style="min-width:115px"><div class="progress"><span style="width:${Math.min(100,i.balance/i.credit*100)}%;background:${i.balance>i.credit?'#c94d4c':'#d39c5c'}"></span></div><small>${NUM(i.balance/i.credit*100,0)}% limitu</small></div>`,`${i.days} dni`,i.balance>i.credit?'<span class="tag red">Blokada</span>':'<span class="tag green">W normie</span>',can('investors.write')?btn(icon('edit')+' Edytuj','edit-investor','btn-small',`data-id="${i.id}"`):'-']));let actions=can('investors.write')?btn(icon('plus')+' Dodaj inwestora','new-investor'):'';return head('Inwestorzy i budowy','Limity kredytowe, rozrachunki i etapy realizowanych inwestycji.',actions)+`<div class="stats">${card('Obsługiwane projekty',S.investors.length,'Konta inwestorskie')}${card('Łączne limity',PLN(S.investors.reduce((a,i)=>a+i.credit,0)),'Kredyt kupiecki')}${card('Należności',PLN(S.investors.reduce((a,i)=>a+i.balance,0)),'Bieżący stan analityczny')}${card('Przekroczone limity',S.investors.filter(i=>i.balance>i.credit).length,'Wymagają decyzji')}</div><div class="toolbar">${searchbar('Szukaj inwestora lub inwestycji...')}</div>`+panel('Portfel inwestorów','Warunki płatności są ustalane per kontrahent',table(['Inwestor / projekt','Etap','Limit','Należność','Wykorzystanie','Termin','Ryzyko','Działanie'],rows));}
function stockPage(){let q=ui.search.toLowerCase(),rows=S.products.filter(p=>(ui.filter==='all'||p.cat===ui.filter)&&[p.id,p.name].join(' ').toLowerCase().includes(q)).map(p=>tr([`<strong>${e(p.name)}</strong><small>${e(p.id)} · ${e(CATEGORIES[p.cat])}</small>`,NUM(p.stock,1)+' '+e(p.unit),NUM(reserved(p.id),1),`<strong>${NUM(available(p.id),1)} ${e(p.unit)}</strong>`,NUM(p.min,1),PLN(p.cost),PLN(p.price),available(p.id)<p.min?'<span class="tag red">Uzupełnij</span>':'<span class="tag green">OK</span>']));let actions=can('stock.write')?btn(icon('plus')+' Ruch magazynowy','stock-move'):'';return head('Magazyny i stany','Rezerwacje, przyjęcia PZ, wydania WZ i minimalne stany produktów.',actions)+`<div class="toolbar">${searchbar('Nazwa lub kod towaru...')}${selectfilter(Object.entries(CATEGORIES).filter(x=>x[0]!=='ext'))}${can('stock.write')?btn('Nowy produkt','new-product','btn'):''}</div>`+panel('Kartoteka materiałów',`${S.products.length} aktywnych produktów, stany fizyczne i dostępne`,table(['Nazwa / dział','Na stanie','Rezerwacja','Dostępne','Min.','Koszt jedn.','Cena netto','Stan'],rows))+panel('Ostatnie ruchy PZ / WZ','Zmiany zapasów powiązane ze źródłem',table(['Kiedy','Dokument','Towar','Ilość','Źródło'],S.movements.slice(0,8).map(m=>tr([DATE(m.date),e(m.kind),e(product(m.id)?.name),`${m.qty>0?'+':''}${NUM(m.qty,2)} ${e(product(m.id)?.unit)}`,e(m.source)]))));}
function purchasesPage(){let q=ui.search.toLowerCase(),rows=S.purchases.filter(p=>[p.id,product(p.productId)?.name,supplier(p.supplierId)?.name].join(' ').toLowerCase().includes(q)).map(p=>tr([`<strong>${e(p.id)}</strong><small>${DATE(p.date)}</small>`,e(supplier(p.supplierId)?.name),e(product(p.productId)?.name),NUM(p.qty,1)+' '+e(product(p.productId)?.unit),PLN(p.unitCost*p.qty),tag(p.status),p.status==='draft'&&can('purchases.write')?btn('Zamów','order-purchase','btn-small',`data-id="${p.id}"`):p.status==='ordered'&&can('purchases.receive')?btn('Przyjmij PZ','receive-purchase','btn-small',`data-id="${p.id}"`):'-']));let actions=can('purchases.write')?btn(icon('plus')+' Zamów dostawę','new-purchase'):'';return head('Zakupy i dostawcy','Zapotrzebowania, zamówienia do dostawców, kontrola stanów i przyjęcia.',actions)+panel('Rekomendacje zakupowe','Towary poniżej przyjętego minimum',`<div class="panel-content"><div class="grid3">${S.products.filter(p=>available(p.id)<p.min).map(p=>`<div class="mini-card"><span class="tag amber">Brak minimum</span><h3 style="margin-top:12px">${e(p.name)}</h3><p>Dostępne ${NUM(available(p.id),1)} ${e(p.unit)}. Minimum ${NUM(p.min,1)} ${e(p.unit)}.</p>${can('purchases.write')?`<p style="margin-top:12px">${btn('Zamów uzupełnienie','quick-purchase','btn btn-small',`data-id="${p.id}"`)}</p>`:''}</div>`).join('')||'<p class="note">Nie ma pilnych braków.</p>'}</div></div>`)+`<div class="toolbar">${searchbar('Szukaj zakupu lub dostawcy...')}${can('purchases.write')?btn('Dodaj dostawcę','new-supplier','btn'):''}</div>`+panel('Zamówienia zakupowe',`${S.purchases.length} pozycji`,table(['Dokument','Dostawca','Towar','Ilość','Wartość netto','Status','Akcja'],rows));}
function sawmillPage(){let rows=S.mills.map(j=>{let raw=product(j.input),out=product(j.output),qty=j.volume*j.yield,cost=j.volume*n(raw?.cost)+n(j.energy)+n(j.labor)+n(j.other),unit=qty?cost/qty:0,margin=out?.price?(out.price-unit)/out.price:0;return tr([`<strong>${e(j.id)}</strong><small>${DATE(j.date)}</small>`,e(raw?.name),NUM(j.volume,2)+' m³',PCT(j.yield),NUM(qty,2)+' m³',PLN(unit),`<span style="color:${margin<0?'#c94d4c':'#168267'};font-weight:800">${PCT(margin)}</span>`,tag(j.status),j.status==='planned'&&can('sawmill.write')?btn('Zakończ','finish-job','btn-small',`data-id="${j.id}"`):'-'])});let actions=can('sawmill.write')?btn(icon('plus')+' Nowe zlecenie','new-job'):'';return head('Tartak i produkcja','Koszt m³, uzysk surowca, energia, robocizna i marża wyrobu.',actions)+`<div class="alert blue">${icon('tree')} Zakończenie zlecenia sprawdza dostępność surowca, rozchoduje drewno i przyjmuje gotową tarcicę. Koszt jednostkowy wyrobu jest przeliczany średnią ważoną.</div>`+panel('Zlecenia produkcyjne','Przykładowe dane technologiczne i koszty',table(['Nr','Surowiec','Wejście','Uzysk','Wyjście','Koszt m³','Marża %','Status','Działanie'],rows));}
